Coin::collision(MovingObject& other, const CollisionHit& )
{
  auto player = dynamic_cast<Player*>(&other);
  if (player == nullptr)
    return ABORT_MOVE;
  if (m_col.get_bbox().overlaps(player->get_bbox().grown(-0.1f)))
    collect();
  return ABORT_MOVE;
}

/* The following defines a coin subject to gravity. */
HeavyCoin::HeavyCoin(const Vector& pos, const Vector& init_velocity, bool count_stats, const std::string& sprite_path) :
  Coin(pos, count_stats, sprite_path),
  m_physic(),
  m_last_hit()
{
  m_physic.enable_gravity(true);
  SoundManager::current()->preload("sounds/coin2.ogg");
  set_group(COLGROUP_MOVING);
  m_physic.set_velocity(init_velocity);
}

HeavyCoin::HeavyCoin(const ReaderMapping& reader, bool count_stats) :
  Coin(reader, count_stats),
  m_physic(),
  m_last_hit()
{
  m_physic.enable_gravity(true);
  SoundManager::current()->preload("sounds/coin2.ogg");
  set_group(COLGROUP_MOVING);
}

void
HeavyCoin::update(float dt_sec)
{
  // Enable physics.
  m_col.set_movement(m_physic.get_movement(dt_sec));
}

void
HeavyCoin::collision_solid(const CollisionHit& hit)
{
  float clink_threshold = 100.0f; // Sets the minimum speed needed to result in collision noise.
  // TODO: Colliding with HeavyCoins should have their own unique sound.

  if (hit.bottom) {
    if (m_physic.get_velocity_y() > clink_threshold && !m_last_hit.bottom)
        SoundManager::current()->play("sounds/coin2.ogg", get_pos());
    if (m_physic.get_velocity_y() > 200) {// lets some coins bounce
      m_physic.set_velocity_y(-99);
    } else {
      m_physic.set_velocity_y(0);
    }
  }
  if (hit.right || hit.left) {
    if ((m_physic.get_velocity_x() > clink_threshold ||
         m_physic.get_velocity_x()< -clink_threshold) &&
         hit.right != m_last_hit.right && hit.left != m_last_hit.left)
      SoundManager::current()->play("sounds/coin2.ogg", get_pos());
    m_physic.set_velocity_x(-m_physic.get_velocity_x());
  }
  if (hit.top) {
    if (m_physic.get_velocity_y() < -clink_threshold && !m_last_hit.top)
      SoundManager::current()->play("sounds/coin2.ogg", get_pos());
    m_physic.set_velocity_y(-m_physic.get_velocity_y());
  }

  // Only make a sound if the coin wasn't hittin anything last frame (A coin
  // stuck in solid matter would flood the sound manager - see #1555 on GitHub).
  m_last_hit = hit;
}

void
Coin::move_to(const Vector& pos)
{
  Vector shift = pos - m_col.m_bbox.p1();
  if (get_path()) {
    get_path()->move_by(shift);
  }
  set_pos(pos);
}

ObjectSettings
Coin::get_settings()
{
  ObjectSettings result = MovingSprite::get_settings();

  result.add_path_ref(_("Path"), *this, get_path_ref(), "path-ref");
  m_add_path = has_valid_path();
  result.add_bool(_("Following path"), &m_add_path);

  if (m_add_path) {
    result.add_walk_mode(_("Path Mode"), &get_path()->m_mode, {}, {});
    result.add_bool(_("Adapt Speed"), &get_path()->m_adapt_speed, {}, {});
    result.add_int(_("Starting Node"), &m_starting_node, "starting-node", 0, 0U);
    result.add_path_handle(_("Handle"), m_path_handle, "handle");
  }

  result.add_script(get_uid(), _("Collect script"), &m_collect_script, "collect-script");

  result.reorder({"collect-script", "path-ref"});

  return result;
}

void
Coin::after_editor_set()
{
  MovingSprite::after_editor_set();

  if (get_walker() && get_path()->is_valid()) {
    if (!m_add_path) {
      get_path()->m_nodes.clear();
    }
  } else {
    if (m_add_path) {
      init_path_pos(m_col.m_bbox.p1());
    }
  }
}

void
Coin::on_flip(float height)
{
  MovingSprite::on_flip(height);
  PathObject::on_flip();
  FlipLevelTransformer::transform_flip(m_flip);
}

ObjectSettings
HeavyCoin::get_settings()
{
  auto result = MovingSprite::get_settings();

  result.add_script(get_uid(), _("Collect script"), &m_collect_script, "collect-script");

  result.reorder({"collect-script", "sprite", "x", "y"});

  return result;
}

void
HeavyCoin::after_editor_set()
{
  MovingSprite::after_editor_set();
}

void
HeavyCoin::on_flip(float height)
{
  // Call on_flip from grandparent class MovingSprite to
  // avoid flipping of gravity-affected object HeavyCoin.
  MovingSprite::on_flip(height);
}

#include "object/coin_explode.hpp"

#include "math/random.hpp"
#include "object/coin.hpp"
#include "supertux/sector.hpp"

#include <array>

CoinExplode::CoinExplode(const Vector& pos, bool count_stats, const std::string& sprite) :
  m_sprite(sprite),
  position(pos),
  m_count_stats(count_stats)
{
}

void
CoinExplode::update(float )
{
  float mag = 100.0f; // Magnitude at which coins are thrown.
  float rand = 30.0f; // Max variation to be subtracted from the magnitude.

  // Each coin in the explosion has a different velocity. Only one half of
  // the fan is listed; every entry is thrown twice, once mirrored.
  static const std::array<Vector, 5> coin_velocities = {{
    { 2.5f, -4.5f }, { 2.f, -5.f },
    { 1.5f, -5.5f }, { 1.f, -6.f }, { 0.5f, -6.5f }
  }};

  for (const auto& vector : coin_velocities)
  {
    for (const float side : { 1.f, -1.f })
    {
      const Vector velocity = Vector(vector.x, vector.y * side) * (mag - gameRandom.randf(rand));
      Sector::get().add<HeavyCoin>(position, velocity, m_count_stats, m_sprite);
    }
  }

  remove_me();
}

void
CoinExplode::draw(DrawingContext &)
{
}

#include "object/coin_rain.hpp"

#include "math/random.hpp"
#include "object/coin.hpp"
#include "sprite/sprite.hpp"
#include "sprite/sprite_manager.hpp"
#include "supertux/sector.hpp"

static const float DROP_TIME = .1f; // Time duration between "drops" of coin rain.

CoinRain::CoinRain(const Vector& pos, bool emerge, bool count_stats, const std::string& sprite_path) :
  sprite(SpriteManager::current()->create(sprite_path)),
  m_sprite_path(sprite_path),
  position(pos),
  emerge_distance(0),
  timer(),
  counter(0),
  drop(0),
  m_count_stats(count_stats)
{
  if (emerge) {
    emerge_distance = static_cast<float>(sprite->get_height());
  }
}

void
CoinRain::update(float dt_sec)
{
  // First a single (untouchable) coin flies up above the sector.
  if (position.y > -32){
    float dist = -500 * dt_sec;
    position.y += dist;
    emerge_distance += dist;
  } // Then the first collectable coin drops from one of ten random positions.
  else if (counter==0){
    drop = gameRandom.rand(10);
    Sector::get().add<HeavyCoin>(Vector(position.x + 32.0f * static_cast<float>((drop < 5) ? -drop - 1 : drop - 4), -32.0f),
                                                              Vector(0, 0), m_count_stats, m_sprite_path);
    counter++;
    timer.start(DROP_TIME);
  } // Finally, the remaining coins drop in a determined but seemingly random order.
  else if (timer.check()){
    if (counter<10){
      drop += 7;
      if (drop >= 10) drop -=10;
      Sector::get().add<HeavyCoin>(Vector(position.x + 32.0f * static_cast<float>((drop < 5) ? -drop - 1 : drop - 4), -32.0f),
                                                                Vector(0, 0), m_count_stats, m_sprite_path);
      counter++;
      timer.start(DROP_TIME);
    } else {
      remove_me();
    }
  }
}

void
CoinRain::draw(DrawingContext& context)
{
  int layer;
  if (emerge_distance > 0) {
    layer = LAYER_OBJECTS - 5;
  } else {
    layer = LAYER_OBJECTS + 5;
  }
  sprite->draw(context.color(), position, layer);
}

